/* 工具条上的小气泡（WarmTip / WarmTipGroup）
   一组气泡只养一个盒子。手从这颗按钮滑到旁边那颗，盒子不重开也不重弹 ——
   它自己滑过去，字在里面按方向换人。刚刚露过一次脸之后的一小段时间
   （warmWindow）里再来，不用等，直接出来；过了这段就得重新熬 delay，
   熬的时候触发点上有一条引线在走。

   位置是 JS 一格一格推出来的（CSS 过渡管不住「一路滑过去」），尺寸交给
   CSS 过渡，字交给关键帧。减少动效时全都一步到位。 */

import {
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type ReactElement,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import "./warm-tip.css";

export type WarmTipSide = "top" | "bottom" | "left" | "right";
export type WarmTipSize = "sm" | "md" | "lg";

const FONT_SIZE: Record<WarmTipSize, number> = { sm: 11.5, md: 12.5, lg: 13.5 };

/* 手从一颗挪到旁边那颗的间隙 —— 这么短的时间里盒子不该断。 */
const HOP_GRACE = 80;
/* 收起一口气的时间，跟 CSS 里那次淡出对齐。 */
const CLOSE_MS = 160;
/* 换字的动画时长；幽灵层等它自己的 animationend 下场，这条只是兜底。 */
const SWAP_MS = 320;

const ARROW = 8;
const VIEWPORT_PAD = 8;
const ARROW_INSET = 14;

type TipKind = "pop" | "plain" | "travel";

interface Face {
  content: ReactNode;
  shortcut?: string;
  side: WarmTipSide;
  surface: string;
  ink: string;
  radius: number;
  gap: number;
  arrow: boolean;
  size: WarmTipSize;
  popMs: number;
  popScale: number;
  popBlur: number;
  showFuse: boolean;
  delay?: number;
  longPress: number;
}

interface Target {
  key: string;
  el: HTMLElement;
  face: Face;
}

interface Session {
  target: Target;
  kind: TipKind;
  swap: boolean;
  dir: number;
  seq: number;
  open: boolean;
}

interface Geom {
  x: number;
  y: number;
  w: number;
  h: number;
  ax: number;
  ay: number;
}

interface Bus {
  tipId: string;
  delay: number;
  enter: (target: Target, instant?: boolean) => void;
  leave: (key: string) => void;
  press: (target: Target) => void;
  release: () => void;
  drop: (key: string) => void;
}

const busCtx = createContext<Bus | null>(null);
const stateCtx = createContext<{ arming: string | null; active: string | null }>({
  arming: null,
  active: null,
});

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function quietMotion() {
  return (
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches
  );
}

function sameGeom(a: Geom, b: Geom) {
  return a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h && a.ax === b.ax && a.ay === b.ay;
}

/* 盒子该落在哪儿：先贴着触发点摆，出了视口就往里收；箭头沿边咬住触发点的中心。 */
function place(el: HTMLElement, w: number, h: number, face: Face): Geom {
  const rect = el.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  let x: number;
  let y: number;
  switch (face.side) {
    case "top":
      x = cx - w / 2;
      y = rect.top - face.gap - h;
      break;
    case "bottom":
      x = cx - w / 2;
      y = rect.bottom + face.gap;
      break;
    case "left":
      x = rect.left - face.gap - w;
      y = cy - h / 2;
      break;
    default:
      x = rect.right + face.gap;
      y = cy - h / 2;
      break;
  }
  x = clamp(x, VIEWPORT_PAD, Math.max(VIEWPORT_PAD, window.innerWidth - w - VIEWPORT_PAD));
  y = clamp(y, VIEWPORT_PAD, Math.max(VIEWPORT_PAD, window.innerHeight - h - VIEWPORT_PAD));

  let ax: number;
  let ay: number;
  if (face.side === "top" || face.side === "bottom") {
    const along = clamp(cx - x, Math.min(ARROW_INSET, w / 2), Math.max(w - ARROW_INSET, w / 2));
    ax = Math.round(along - ARROW / 2);
    ay = face.side === "top" ? h - ARROW / 2 - 1 : -ARROW / 2 + 1;
  } else {
    const along = clamp(cy - y, Math.min(ARROW_INSET, h / 2), Math.max(h - ARROW_INSET, h / 2));
    ay = Math.round(along - ARROW / 2);
    ax = face.side === "left" ? w - ARROW / 2 - 1 : -ARROW / 2 + 1;
  }
  return { x: Math.round(x), y: Math.round(y), w, h, ax, ay };
}

export interface WarmTipGroupProps {
  children: ReactNode;
  delay?: number;
  warmWindow?: number;
  travel?: number;
  lean?: number;
  onWarmChange?: (warm: boolean) => void;
}

export function WarmTipGroup({
  children,
  delay = 400,
  warmWindow = 300,
  travel = 320,
  lean = 0,
  onWarmChange,
}: WarmTipGroupProps) {
  const tipId = useId();
  const [session, setSession] = useState<Session | null>(null);
  const [geom, setGeom] = useState<Geom | null>(null);
  const [ghost, setGhost] = useState<{ content: ReactNode; shortcut?: string; dir: number } | null>(
    null,
  );
  const [arming, setArming] = useState<string | null>(null);
  const [active, setActive] = useState<string | null>(null);

  const sessionRef = useRef<Session | null>(null);
  const targetRef = useRef<Target | null>(null);
  const outerRef = useRef<HTMLDivElement | null>(null);
  const rulerRef = useRef<HTMLDivElement | null>(null);
  const posRef = useRef({ x: 0, y: 0 });
  const glideRef = useRef<number | null>(null);
  const seqRef = useRef(0);
  const warmRef = useRef(0);
  const warmOnRef = useRef(false);
  const waitRef = useRef<number | null>(null);
  const graceRef = useRef<number | null>(null);
  const exitRef = useRef<number | null>(null);
  const warmOffRef = useRef<number | null>(null);
  const leanRef = useRef(lean);
  const quietRef = useRef(quietMotion());
  const notifyRef = useRef(onWarmChange);

  leanRef.current = lean;
  notifyRef.current = onWarmChange;

  const commit = useCallback((next: Session | null) => {
    sessionRef.current = next;
    setSession(next);
  }, []);

  const clearTimers = useCallback(() => {
    for (const ref of [waitRef, graceRef, exitRef]) {
      if (ref.current !== null) window.clearTimeout(ref.current);
      ref.current = null;
    }
  }, []);

  /* 「热」是有时限的：这会儿再来直接出来，过点了就凉，重新熬 delay。 */
  const markWarm = useCallback((ms: number) => {
    warmRef.current = performance.now() + ms;
    if (!warmOnRef.current) {
      warmOnRef.current = true;
      notifyRef.current?.(true);
    }
    if (warmOffRef.current !== null) window.clearTimeout(warmOffRef.current);
    warmOffRef.current = window.setTimeout(() => {
      warmOffRef.current = null;
      warmOnRef.current = false;
      notifyRef.current?.(false);
    }, ms);
  }, []);

  const paint = useCallback((x: number, y: number, deg: number) => {
    const el = outerRef.current;
    if (!el) return;
    el.style.transform = deg
      ? `translate3d(${x}px, ${y}px, 0) rotate(${deg}deg)`
      : `translate3d(${x}px, ${y}px, 0)`;
  }, []);

  const stopGlide = useCallback(() => {
    if (glideRef.current !== null) {
      cancelAnimationFrame(glideRef.current);
      glideRef.current = null;
    }
  }, []);

  /* 滑过去：横向走得越远，身子歪得越多，中间最多 lean 度，落回正。 */
  const glide = useCallback(
    (from: { x: number; y: number }, to: { x: number; y: number }, ms: number) => {
      stopGlide();
      const peak = clamp((to.x - from.x) / 40, -1, 1) * leanRef.current;
      if (ms <= 0) {
        paint(to.x, to.y, 0);
        return;
      }
      const t0 = performance.now();
      const step = () => {
        const t = Math.min(1, (performance.now() - t0) / ms);
        const eased = 1 - Math.pow(1 - t, 3);
        paint(
          from.x + (to.x - from.x) * eased,
          from.y + (to.y - from.y) * eased,
          peak * Math.sin(Math.PI * t),
        );
        if (t < 1) glideRef.current = requestAnimationFrame(step);
        else {
          glideRef.current = null;
          paint(to.x, to.y, 0);
        }
      };
      glideRef.current = requestAnimationFrame(step);
    },
    [paint, stopGlide],
  );

  const sync = useCallback(
    (animate: boolean) => {
      const current = sessionRef.current;
      const ruler = rulerRef.current;
      if (!current || !current.open || !ruler) return;
      if (!current.target.el.isConnected) {
        commit(null);
        return;
      }
      // 尺子量到的是内容本身（不含内边距），盒子写死的尺寸得把内边距加回去。
      const measured = ruler.getBoundingClientRect();
      const boxEl = ruler.parentElement;
      const styles = boxEl ? getComputedStyle(boxEl) : null;
      const padX = styles
        ? parseFloat(styles.paddingLeft) + parseFloat(styles.paddingRight)
        : 0;
      const padY =
        styles ? parseFloat(styles.paddingTop) + parseFloat(styles.paddingBottom) : 0;
      const w = Math.max(1, Math.round(measured.width + padX));
      const h = Math.max(1, Math.round(measured.height + padY));
      const next = place(current.target.el, w, h, current.target.face);
      setGeom((prev) => (prev && sameGeom(prev, next) ? prev : next));
      const from = posRef.current;
      posRef.current = { x: next.x, y: next.y };
      if (animate && !quietRef.current) glide(from, { x: next.x, y: next.y }, travel);
      else {
        stopGlide();
        paint(next.x, next.y, 0);
      }
    },
    [commit, glide, paint, stopGlide, travel],
  );

  const hide = useCallback(() => {
    clearTimers();
    setArming(null);
    targetRef.current = null;
    const current = sessionRef.current;
    if (!current || !current.open) return;
    markWarm(warmWindow);
    setActive(null);
    commit({ ...current, open: false });
    exitRef.current = window.setTimeout(() => {
      exitRef.current = null;
      commit(null);
      setGhost(null);
      posRef.current = { x: 0, y: 0 };
    }, CLOSE_MS);
  }, [clearTimers, commit, markWarm, warmWindow]);

  const show = useCallback(
    (target: Target, kind: TipKind, dir: number) => {
      clearTimers();
      setArming(null);
      targetRef.current = target;
      markWarm(warmWindow);
      seqRef.current += 1;
      const prev = sessionRef.current;
      // 减少动效时不摆幽灵层 —— 那层的动画本来就不跑，留着只会两行字叠在一起。
      const swap =
        kind === "travel" &&
        !quietRef.current &&
        !!prev &&
        prev.target.face.content !== target.face.content;
      if (swap && prev) {
        setGhost({ content: prev.target.face.content, shortcut: prev.target.face.shortcut, dir });
      }
      setActive(target.key);
      commit({ target, kind, swap, dir, seq: seqRef.current, open: true });
    },
    [clearTimers, commit, markWarm, warmWindow],
  );

  const enter = useCallback(
    (target: Target, instant = false) => {
      clearTimers();
      targetRef.current = target;
      const current = sessionRef.current;
      if (current && current.open) {
        const prevEl = current.target.el;
        const dir = Math.sign(target.el.getBoundingClientRect().left - prevEl.getBoundingClientRect().left) || 1;
        show(target, "travel", dir);
        return;
      }
      if (instant) {
        show(target, "pop", 1);
        return;
      }
      if (performance.now() < warmRef.current) {
        show(target, "plain", 1);
        return;
      }
      setArming(target.key);
      waitRef.current = window.setTimeout(() => {
        waitRef.current = null;
        if (targetRef.current?.key === target.key) show(target, "pop", 1);
      }, target.face.delay ?? delay);
    },
    [clearTimers, delay, show],
  );

  const leave = useCallback(
    (key: string) => {
      if (targetRef.current?.key === key) targetRef.current = null;
      if (waitRef.current !== null) {
        window.clearTimeout(waitRef.current);
        waitRef.current = null;
      }
      setArming((value) => (value === key ? null : value));
      if (!sessionRef.current?.open) return;
      if (graceRef.current !== null) window.clearTimeout(graceRef.current);
      graceRef.current = window.setTimeout(() => {
        graceRef.current = null;
        hide();
      }, HOP_GRACE);
    },
    [hide],
  );

  const press = useCallback(
    (target: Target) => {
      if (waitRef.current !== null) window.clearTimeout(waitRef.current);
      waitRef.current = window.setTimeout(() => {
        waitRef.current = null;
        show(target, "pop", 1);
      }, target.face.longPress);
    },
    [show],
  );

  const release = useCallback(() => {
    if (waitRef.current !== null) {
      window.clearTimeout(waitRef.current);
      waitRef.current = null;
    }
    setArming(null);
  }, []);

  const drop = useCallback(
    (key: string) => {
      if (targetRef.current?.key === key) targetRef.current = null;
      setArming((value) => (value === key ? null : value));
      if (sessionRef.current?.target.key === key) hide();
    },
    [hide],
  );

  /* 量位置、摆位置。第一帧量不到就藏起来，量到了再现身（都发生在画之前）。 */
  useLayoutEffect(() => {
    if (!session || !session.open) return;
    sync(session.kind === "travel");
  }, [session, sync]);

  /* 幽灵层只活一次换字的时间：动画自己报收尾就下场，报不了（减少动效）才等兜底。 */
  useEffect(() => {
    if (!ghost) return;
    const timer = window.setTimeout(() => setGhost(null), SWAP_MS);
    return () => window.clearTimeout(timer);
  }, [ghost]);

  /* 开着的时候跟着页面走。 */
  useEffect(() => {
    if (!session?.open) return;
    const follow = () => sync(false);
    window.addEventListener("scroll", follow, true);
    window.addEventListener("resize", follow);
    return () => {
      window.removeEventListener("scroll", follow, true);
      window.removeEventListener("resize", follow);
    };
  }, [session?.open, sync]);

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape" && sessionRef.current?.open) hide();
    };
    const onPointerDown = (event: PointerEvent) => {
      const current = sessionRef.current;
      if (!current?.open) return;
      if (current.target.el.contains(event.target as Node)) return;
      hide();
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown, true);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown, true);
    };
  }, [hide]);

  useEffect(
    () => () => {
      clearTimers();
      stopGlide();
      if (warmOffRef.current !== null) window.clearTimeout(warmOffRef.current);
    },
    [clearTimers, stopGlide],
  );

  const bus = useMemo<Bus>(
    () => ({ tipId, delay, enter, leave, press, release, drop }),
    [tipId, delay, enter, leave, press, release, drop],
  );
  const state = useMemo(() => ({ arming, active }), [arming, active]);

  const face = session?.target.face;
  const vars: Record<string, string> = face
    ? {
        "--wt-surface": face.surface,
        "--wt-ink": face.ink,
        "--wt-radius": `${face.radius}px`,
        "--wt-font": `${FONT_SIZE[face.size]}px`,
        "--wt-pop-ms": `${face.popMs}ms`,
        "--wt-pop-scale": String(face.popScale),
        "--wt-pop-blur": `${face.popBlur}px`,
        "--wt-pop-lift": face.side === "top" ? "4px" : face.side === "bottom" ? "-4px" : "0px",
      }
    : {};

  return (
    <busCtx.Provider value={bus}>
      <stateCtx.Provider value={state}>{children}</stateCtx.Provider>
      {session
        ? createPortal(
            <div
              ref={outerRef}
              id={tipId}
              role="tooltip"
              className="warm-tip"
              data-ready={geom ? "true" : "false"}
              data-open={session.open ? "true" : "false"}
              data-side={face?.side ?? "top"}
              style={vars as CSSProperties}
            >
              <div
                className="warm-tip__pop"
                data-pop={session.open && session.kind === "pop" ? "true" : "false"}
                data-instant={session.open && session.kind === "plain" ? "true" : "false"}
              >
                <div
                  className="warm-tip__box"
                  data-swap={session.swap ? "true" : "false"}
                  style={geom ? { width: geom.w, height: geom.h } : undefined}
                >
                  <div ref={rulerRef} className="warm-tip__ruler" aria-hidden="true">
                    <TipText content={face?.content} shortcut={face?.shortcut} />
                  </div>
                  {ghost ? (
                    <div
                      className="warm-tip__face"
                      data-role="out"
                      aria-hidden="true"
                      style={{ "--wt-dir": String(ghost.dir) } as CSSProperties}
                      onAnimationEnd={() => setGhost(null)}
                    >
                      <TipText content={ghost.content} shortcut={ghost.shortcut} />
                    </div>
                  ) : null}
                  <div
                    key={`face-${session.seq}`}
                    className="warm-tip__face"
                    data-role="in"
                    style={{ "--wt-dir": String(session.dir) } as CSSProperties}
                  >
                    <TipText content={face?.content} shortcut={face?.shortcut} />
                  </div>
                </div>
                {face?.arrow === false ? null : (
                  <span
                    className="warm-tip__arrow"
                    style={geom ? { left: geom.ax, top: geom.ay } : undefined}
                  />
                )}
              </div>
            </div>,
            document.body,
          )
        : null}
    </busCtx.Provider>
  );
}

function TipText({ content, shortcut }: { content?: ReactNode; shortcut?: string }) {
  return (
    <span className="warm-tip__text">
      <span className="warm-tip__label">{content}</span>
      {shortcut ? <kbd className="warm-tip__kbd">{shortcut}</kbd> : null}
    </span>
  );
}

export interface WarmTipProps {
  content: ReactNode;
  children: ReactNode;
  shortcut?: string;
  side?: WarmTipSide;
  delay?: number;
  surfaceColor?: string;
  inkColor?: string;
  size?: WarmTipSize;
  radius?: number;
  gap?: number;
  arrow?: boolean;
  popDuration?: number;
  popScale?: number;
  popBlur?: number;
  showFuse?: boolean;
  longPress?: number;
  disabled?: boolean;
  className?: string;
}

/* 没有组就自己带一个组 —— 单颗气泡也能用。 */
export function WarmTip(props: WarmTipProps) {
  const bus = useContext(busCtx);
  if (bus) return <WarmTipAnchor {...props} bus={bus} />;
  return (
    <WarmTipGroup>
      <SoloAnchor {...props} />
    </WarmTipGroup>
  );
}

function SoloAnchor(props: WarmTipProps) {
  const bus = useContext(busCtx);
  if (!bus) return null;
  return <WarmTipAnchor {...props} bus={bus} />;
}

function WarmTipAnchor({
  content,
  children,
  shortcut,
  side = "top",
  delay,
  surfaceColor = "#f5f5f5",
  inkColor = "#18181b",
  size = "md",
  radius = 8,
  gap = 8,
  arrow = true,
  popDuration = 160,
  popScale = 0.94,
  popBlur = 4,
  showFuse = false,
  longPress = 500,
  disabled = false,
  className,
  bus,
}: WarmTipProps & { bus: Bus }) {
  const key = useId();
  const anchorRef = useRef<HTMLSpanElement | null>(null);
  const [pressing, setPressing] = useState(false);
  const state = useContext(stateCtx);
  const open = state.active === key;
  const armed = state.arming === key;

  const target = useCallback((): Target | null => {
    const el = anchorRef.current;
    if (!el || disabled) return null;
    return {
      key,
      el,
      face: {
        content,
        shortcut,
        side,
        surface: surfaceColor,
        ink: inkColor,
        radius,
        gap,
        arrow,
        size,
        popMs: popDuration,
        popScale,
        popBlur,
        showFuse,
        delay,
        longPress,
      },
    };
  }, [
    key,
    disabled,
    content,
    shortcut,
    side,
    surfaceColor,
    inkColor,
    radius,
    gap,
    arrow,
    size,
    popDuration,
    popScale,
    popBlur,
    showFuse,
    delay,
    longPress,
  ]);

  useEffect(
    () => () => {
      bus.drop(key);
    },
    [bus, key],
  );

  const describedBy = open
    ? (() => {
        const own = isValidElement(children)
          ? (children as ReactElement<Record<string, unknown>>).props["aria-describedby"]
          : undefined;
        return typeof own === "string" && own ? `${own} ${bus.tipId}` : bus.tipId;
      })()
    : null;

  return (
    <span
      ref={anchorRef}
      className={className ? `warm-tip-anchor ${className}` : "warm-tip-anchor"}
      data-pressing={pressing ? "true" : "false"}
      onPointerEnter={(event) => {
        if (event.pointerType === "touch") return;
        const next = target();
        if (next) bus.enter(next);
      }}
      onPointerLeave={(event) => {
        if (event.pointerType === "touch") return;
        bus.leave(key);
      }}
      onFocus={() => {
        const next = target();
        if (next) bus.enter(next, true);
      }}
      onBlur={() => bus.leave(key)}
      onPointerDown={(event) => {
        if (event.pointerType !== "touch") return;
        setPressing(true);
        const next = target();
        if (next) bus.press(next);
      }}
      onPointerUp={() => {
        setPressing(false);
        bus.release();
      }}
      onPointerCancel={() => {
        setPressing(false);
        bus.release();
      }}
    >
      {describedBy && isValidElement(children)
        ? cloneElement(children as ReactElement<Record<string, unknown>>, {
            "aria-describedby": describedBy,
          })
        : children}
      {showFuse ? (
        <span
          className="warm-tip-fuse"
          aria-hidden="true"
          data-side={side}
          data-arming={armed ? "true" : "false"}
          style={
            {
              "--wt-fuse-ms": `${delay ?? bus.delay}ms`,
              "--wt-fuse-color": surfaceColor,
            } as CSSProperties
          }
        />
      ) : null}
    </span>
  );
}

export default WarmTip;
