/**
 * 一段字，一格一格地浮出来（RevealText）
 *
 * 站在第三方那套 SplitText（GSAP 加 Club 插件）的位置上，但一行都不欠它：
 * 切格子是自己切 DOM，动的是 Web Animations API，进场交给 IntersectionObserver。
 *
 * 三种切法：
 *   chars —— 每个字一格；字之间不断行，整个词才断行（词外面套一层壳）；
 *   words —— 每个词一格，空格留在格子外面，断行的规矩跟没切过一样；
 *   lines —— 按行分组：先量出每个词落在第几行，同一行走，行与行才错开。
 *
 * 两处细节是特意跟原版不一样的：
 *   · 读屏器听到的是整句（挂在根节点的 aria-label），不是一格一格的碎片；
 *   · 减少动效时不动，直接把字放正 —— 而不是动画还在跑、只是快了。
 */
import {
  Fragment,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ComponentType,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from "react";
import "./reveal-text.css";

export type RevealSplit = "chars" | "words" | "lines";

/** 首尾的样子：只认这几个数，够用了，也不给人乱传的机会。 */
export interface RevealFrame {
  opacity?: number;
  x?: number;
  y?: number;
  scale?: number;
  rotate?: number;
  blur?: number;
}

export interface RevealTextProps {
  text: string;
  className?: string;
  /** 相邻两格错开多少毫秒。 */
  delay?: number;
  /** 每格自己走多久（秒）。 */
  duration?: number;
  /** 缓动。收 gsap 那套名字（power3.out…），也照收 CSS 原话（cubic-bezier(...)）。 */
  ease?: string;
  splitType?: RevealSplit;
  from?: RevealFrame;
  to?: RevealFrame;
  /** 进场判定：露出多少算数、离视口还有多远就开始留意。 */
  threshold?: number;
  rootMargin?: string;
  textAlign?: CSSProperties["textAlign"];
  /** 根节点用什么标签：标题用 h1，段落用 p（也可以直接给个组件）。 */
  tag?: keyof HTMLElementTagNameMap | ComponentType<RevealHostProps>;
  onLetterAnimationComplete?: () => void;
}

/** 根标签上会放的几样东西 —— 就这么几样，说清楚比放开更省事。 */
interface RevealHostProps {
  ref?: Ref<HTMLElement>;
  className?: string;
  style?: CSSProperties;
  "aria-label"?: string;
  children?: ReactNode;
}

/* gsap 的缓动名翻成 CSS 的等价写法：powerN.out = 1-(1-t)^(N+1)。 */
const EASES: Record<string, string> = {
  "power1.out": "cubic-bezier(0.25, 0.46, 0.45, 0.94)",
  "power2.out": "cubic-bezier(0.215, 0.61, 0.355, 1)",
  "power3.out": "cubic-bezier(0.165, 0.84, 0.44, 1)",
  "power4.out": "cubic-bezier(0.23, 1, 0.32, 1)",
  "sine.out": "cubic-bezier(0.39, 0.575, 0.565, 1)",
  "expo.out": "cubic-bezier(0.19, 1, 0.22, 1)",
  "back.out": "cubic-bezier(0.34, 1.56, 0.64, 1)",
  none: "linear",
  linear: "linear",
};

const easeOf = (ease: string) => EASES[ease] ?? ease;

const transformOf = (frame: RevealFrame) =>
  `translate3d(${frame.x ?? 0}px, ${frame.y ?? 0}px, 0)` +
  (frame.scale === undefined ? "" : ` scale(${frame.scale})`) +
  (frame.rotate === undefined ? "" : ` rotate(${frame.rotate}deg)`);

const styleOf = (frame: RevealFrame): CSSProperties => ({
  opacity: frame.opacity ?? 1,
  transform: transformOf(frame),
  ...(frame.blur === undefined ? null : { filter: `blur(${frame.blur}px)` }),
});

const keyframeOf = (frame: RevealFrame): Keyframe => ({
  opacity: frame.opacity ?? 1,
  transform: transformOf(frame),
  ...(frame.blur === undefined ? null : { filter: `blur(${frame.blur}px)` }),
});

/* 按行分组：量每个词落在第几行 —— 同一行的格子一起走。 */
const stepsOf = (pieces: HTMLElement[], split: RevealSplit) => {
  if (split !== "lines") return pieces.map((_, index) => index);
  let line = -1;
  let top = Number.NaN;
  return pieces.map((piece) => {
    if (piece.offsetTop !== top) {
      line += 1;
      top = piece.offsetTop;
    }
    return line;
  });
};

const reducedMotion = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

export function RevealText({
  text,
  className,
  delay = 50,
  duration = 1.25,
  ease = "power3.out",
  splitType = "chars",
  from = { opacity: 0, y: 40 },
  to = { opacity: 1, y: 0 },
  threshold = 0.1,
  rootMargin = "-100px",
  textAlign = "center",
  tag = "p",
  onLetterAnimationComplete,
}: RevealTextProps) {
  const hostRef = useRef<HTMLElement | null>(null);
  const playedRef = useRef(false);
  const doneRef = useRef(false);
  const completeRef = useRef(onLetterAnimationComplete);
  const [done, setDone] = useState(false);

  completeRef.current = onLetterAnimationComplete;

  /* 换了字（书架里翻到另一本）就是另一场：把「跑过了」的记号擦掉重来。
     渲染期改自己的状态是 React 认的写法 —— 别等提交了再补一次渲染。 */
  const runId = `${text}|${splitType}|${delay}|${duration}|${ease}`;
  const [run, setRun] = useState(runId);
  if (run !== runId) {
    setRun(runId);
    setDone(false);
    doneRef.current = false;
    playedRef.current = false;
  }

  /* 词与空格都留着：空格得留在格子外面，断行的规矩才跟没切过一样。 */
  const chunks = useMemo(
    () =>
      text
        .split(/(\s+)/)
        .filter((chunk) => chunk !== "")
        .map((chunk, index) => ({ key: `${index}:${chunk}`, space: /^\s+$/.test(chunk), value: chunk })),
    [text],
  );

  const fromJson = JSON.stringify(from);
  const toJson = JSON.stringify(to);

  useLayoutEffect(() => {
    const host = hostRef.current;
    if (!host || playedRef.current) return undefined;
    const pieces = [...host.querySelectorAll<HTMLElement>("[data-reveal-piece]")];
    if (pieces.length === 0) return undefined;

    let cancelled = false;
    let watching: IntersectionObserver | null = null;
    let running: Animation[] = [];

    const finish = () => {
      if (doneRef.current) return;
      doneRef.current = true;
      setDone(true);
      completeRef.current?.();
    };

    const play = () => {
      if (cancelled || playedRef.current) return;
      playedRef.current = true;
      if (reducedMotion()) {
        finish();
        return;
      }
      const steps = stepsOf(pieces, splitType);
      const stagger = Math.max(0, delay);
      const easing = easeOf(ease);
      running = pieces.map((piece, index) =>
        piece.animate([keyframeOf(from), keyframeOf(to)], {
          duration: Math.max(0, duration) * 1000,
          delay: (steps[index] ?? index) * stagger,
          easing,
          fill: "both",
        }),
      );
      const last = running.at(-1);
      if (!last) {
        finish();
        return;
      }
      last.finished
        .then(() => {
          if (!cancelled) finish();
        })
        .catch(() => {
          /* 被打断就算了，位置由 finish 那一步兜底 */
        });
    };

    const watch = () => {
      if (cancelled) return;
      if (typeof IntersectionObserver === "undefined") {
        play();
        return;
      }
      watching = new IntersectionObserver(
        (entries) => {
          if (!entries.some((entry) => entry.isIntersecting)) return;
          watching?.disconnect();
          watching = null;
          play();
        },
        { threshold, rootMargin },
      );
      watching.observe(host);
    };

    /* 字体没落位之前量行会量歪，等字体。 */
    const fontsReady = typeof document === "undefined" ? undefined : document.fonts?.ready;
    if (fontsReady) void fontsReady.then(watch, watch);
    else watch();

    return () => {
      cancelled = true;
      watching?.disconnect();
      // 没跑完就重跑了：让它一步落到终点，别把字停在半路（fill 会替我们守着）。
      if (playedRef.current && !doneRef.current) {
        running.forEach((animation) => {
          try {
            animation.finish();
          } catch {
            animation.cancel();
          }
        });
      }
    };
  }, [runId, delay, duration, ease, splitType, fromJson, toJson, threshold, rootMargin]);

  /*
   * 根标签的名字是调用方给的（h1 / p …）。直接把一串标签名挂进 JSX，TS 会
   * 把这一百多个标签一起算，最后把 props 收成 never；这里按我们往根上真正
   * 放的那几样东西说清楚，类型就站得住了。
   */
  const Tag = (tag ?? "p") as ComponentType<RevealHostProps>;
  /* 动过之后就别再挂着「还没动」的样子 —— 往后谁来重渲染都动不了它。 */
  const pieceStyle = done ? undefined : styleOf(from);

  return (
    <Tag
      ref={hostRef}
      className={className ? `reveal-text ${className}` : "reveal-text"}
      style={{ textAlign }}
      aria-label={text}
    >
      {chunks.map((chunk) =>
        chunk.space ? (
          <Fragment key={chunk.key}>{chunk.value}</Fragment>
        ) : splitType === "chars" ? (
          <span key={chunk.key} className="reveal-text__word">
            {[...chunk.value].map((char, index) => (
              <span
                key={`${chunk.key}:${index}`}
                className="reveal-text__piece"
                data-reveal-piece="char"
                aria-hidden="true"
                style={pieceStyle}
              >
                {char}
              </span>
            ))}
          </span>
        ) : (
          <span
            key={chunk.key}
            className="reveal-text__piece"
            data-reveal-piece="word"
            aria-hidden="true"
            style={pieceStyle}
          >
            {chunk.value}
          </span>
        ),
      )}
    </Tag>
  );
}

export default RevealText;
